// Local section seconds -> unscaled source seconds. Strictly ordered times,
// nondecreasing values; equal values intentionally hold the child at one time.
export function validSectionTimeWarp(keys){if(keys===undefined)return true;if(!Array.isArray(keys)||keys.length<2||keys.length>256||!keys.every((k,i)=>k&&Object.keys(k).every(p=>p==='time'||p==='value')&&Number.isFinite(k.time)&&k.time>=0&&k.time<=86400&&Number.isFinite(k.value)&&k.value>=0&&k.value<=86400&&(i?k.time>keys[i-1].time&&k.value>=keys[i-1].value:k.time===0&&k.value===0)))return false;for(let i=1;i<keys.length;i++){const slope=(keys[i].value-keys[i-1].value)/(keys[i].time-keys[i-1].time);if(!Number.isFinite(slope)||(i===1||i===keys.length-1)&&!Number.isFinite((86400+slope*86400)*100))return false;}return true;}
export function sampleSectionTimeWarp(keys,time){if(!keys)return time;let lo=0,hi=keys.length;while(lo<hi){const mid=(lo+hi)>>>1;if(keys[mid].time<=time)lo=mid+1;else hi=mid;}const i=Math.max(0,Math.min(keys.length-2,lo-1)),a=keys[i],b=keys[i+1];return a.value+(b.value-a.value)*(time-a.time)/(b.time-a.time);}
