export const sequenceTimeWarpContract=Object.freeze({field:'section.timeWarp?:[{time,value}],2..256 keys; first0,0; finite local parent seconds and unscaled source seconds0..86400; strictly increasing time, nondecreasing value',mapping:'sourceStart + piecewise-linear(timeWarp,parentTime-start)*rate; equal values hold; endpoint segment slopes extrapolate; omitted field keeps old affine mapping; section loop/clamp then applies',events:'Split forward visited ranges at warp knots and shot cuts before child-loop boundaries. Holds do not refire events; pause/seek retain callback suppression. Existing per-piece loop guards remain; no reverse-event contract.',trim:'sequence.section.edit operation trimStart with section:{start} preserves mapped source on surviving times, shifts warp keys and sourceStart together; rejects negative warped source offset. update timeWarp:null removes optional curve.',cost:'Binary point queries on immutable validated keys, no sorting/cloning per sample; visited ranges allocate only crossed warp/shot/loop pieces. No background workers/timers/GPU resources.',remaining:['decreasing/reverse and discontinuous time maps','cubic time-map derivatives and normalized competing-layer blending','device/pull clock/PCM/genlock']});
